namespace OCA\NocturnKalender\Db;

use JsonSerializable;
use OCP\AppFramework\Db\Entity;
use OCP\DB\Types;
use ReturnTypeWillChange;

/**
 * A concrete, dated shift entry on the calendar - either generated by
 * applying a {@see NocturnRotation} template over a date range, or entered
 * manually for a single day independent of any rotation.
 *
 * @method string getUid()
 * @method void setUid(string $uid)
 * @method string getUserId()
 * @method void setUserId(string $userId)
 * @method string getJobUid()
 * @method void setJobUid(string $jobUid)
 * @method int getEpochDay()
 * @method void setEpochDay(int $epochDay)
 * @method string|null getShiftUid()
 * @method void setShiftUid(?string $shiftUid)
 * @method string|null getRotationUid()
 * @method void setRotationUid(?string $rotationUid)
 * @method string getSource()
 * @method void setSource(string $source)
 * @method int getCreatedAt()
 * @method void setCreatedAt(int $createdAt)
 * @method int getUpdatedAt()
 * @method void setUpdatedAt(int $updatedAt)
 * @method int|null getDeletedAt()
 * @method void setDeletedAt(?int $deletedAt)
 */
class NocturnOccurrence extends Entity implements JsonSerializable {
	public const SOURCE_ROTATION = 'rotation';
	public const SOURCE_MANUAL = 'manual';

	/** @var string */
	protected $uid;

	/** @var string */
	protected $userId;

	/** @var string */
	protected $jobUid;

	/** @var int */
	protected $epochDay;

	/** @var string|null */
	protected $shiftUid;

	/** @var string|null */
	protected $rotationUid;

	/** @var string */
	protected $source = self::SOURCE_MANUAL;

	/** @var int */
	protected $createdAt;

	/** @var int */
	protected $updatedAt;

	/** @var int|null */
	protected $deletedAt;

	public function __construct() {
		$this->addType('epochDay', Types::BIGINT);
		$this->addType('createdAt', Types::BIGINT);
		$this->addType('updatedAt', Types::BIGINT);
		$this->addType('deletedAt', Types::BIGINT);
	}

	#[\Override]
	#[ReturnTypeWillChange]
	public function jsonSerialize() {
		return [
			'uid' => $this->getUid(),
			'jobUid' => $this->getJobUid(),
			'epochDay' => $this->getEpochDay(),
			'shiftUid' => $this->getShiftUid(),
			'rotationUid' => $this->getRotationUid(),
			'source' => $this->getSource(),
			'createdAt' => $this->getCreatedAt(),
			'updatedAt' => $this->getUpdatedAt(),
			'deletedAt' => $this->getDeletedAt(),
		];
	}
}
